import{_ as t,o as a,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Plan — Add Workspace Member (FR 3.4.19)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-19-add-workspace-member/plan.md","filePath":"feature/agency-workspace/3-4-19-add-workspace-member/plan.md"}'),c={name:"feature/agency-workspace/3-4-19-add-workspace-member/plan.md"};function i(s,e,d,r,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="plan-—-add-workspace-member-fr-3-4-19" tabindex="-1">Plan — Add Workspace Member (FR 3.4.19) <a class="header-anchor" href="#plan-—-add-workspace-member-fr-3-4-19" aria-label="Permalink to &quot;Plan — Add Workspace Member (FR 3.4.19)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho MANAGER thêm thành viên vào Workspace qua 2 luồng: Invite (mời email) và Assign (gán trực tiếp).</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>WorkspaceServiceImpl.inviteMember()</code>, <code>WorkspaceServiceImpl.assignMembers()</code> → <code>assignMembersInternal()</code>, <code>WorkspaceServiceImpl.acceptInvitation()</code></td></tr><tr><td>File đã có</td><td><code>WorkspaceController</code> (<code>POST /{workspaceId}/members/invite</code>, <code>POST /{workspaceId}/members/assign</code>, <code>POST /invitations/accept</code>), <code>WorkspaceInvitation</code> entity, <code>MailService</code>, <code>AgencyMemberRepository</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/workspaces/{workspaceId}/members/invite</span></span>
<span class="line"><span>{ email, role, note? }</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;null&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/workspaces/{workspaceId}/members/assign</span></span>
<span class="line"><span>{ members: [{ userId, role }] }</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;AssignMembersResponse { added, skippedUserIds }&gt;</span></span></code></pre></div><p>Cả 2 bảo vệ bởi <code>@RequireRole({MemberRole.MANAGER})</code>. Không lệch spec.md.</p><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li><strong>Invite</strong>: <code>INSERT workspace_invitations</code> (status=PENDING, token=UUID, <code>expiresAt = now + 7 ngày</code>, hằng số <code>INVITATION_EXPIRY_DAYS=7</code>). Chưa tạo <code>WorkspaceMember</code> ngay.</li><li><strong>Assign</strong>: <code>INSERT workspace_members</code> ngay (isActive=true), không cần accept. Entry đã active bị skip, đưa vào <code>skippedUserIds</code>.</li><li><strong>Accept invitation</strong>: <code>INSERT workspace_members</code> theo role của invitation, update <code>workspace_invitations.status = ACCEPTED</code>.</li><li>Không migration.</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><p><strong>Flow A — Invite:</strong></p><ol><li><code>@RequireRole(MANAGER)</code> chặn.</li><li>Chuẩn hóa email (<code>trim().toLowerCase()</code>).</li><li>Check đã là active member → 409 <code>ALREADY_IN_WORKSPACE</code>.</li><li>Check invitation PENDING còn hạn → 409 <code>INVITATION_ALREADY_PENDING</code>.</li><li>Nếu <code>role=MANAGER</code> và đã có MANAGER active → 409 <code>MANAGER_ALREADY_ASSIGNED</code>.</li><li>Insert invitation, gửi mail.</li><li>(Nhánh phụ) Accept: validate token/status/expiry/email → insert <code>WorkspaceMember</code>.</li></ol><p><strong>Flow B — Assign:</strong></p><ol><li><code>@RequireRole(MANAGER)</code> chặn.</li><li>Với mỗi entry: check <code>AgencyMember</code> tồn tại → 403 <code>NOT_AGENCY_MEMBER</code>.</li><li>Check đã active → skip (idempotent), thêm vào <code>skippedUserIds</code>.</li><li>Nếu <code>role=MANAGER</code> và đã có MANAGER active → 409 <code>MANAGER_ALREADY_ASSIGNED</code>.</li><li>Check <code>User</code> tồn tại → <code>USER_NOT_FOUND</code>.</li><li>Insert <code>WorkspaceMember</code>, thêm vào <code>added</code>.</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>AgencyMember</code>, <code>WorkspaceInvitation</code>, <code>MailService</code> (đã có)</td></tr><tr><td>Bị chặn</td><td><code>View Workspace Members</code> (3.4.18) — hiển thị kết quả sau khi add</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>2 luồng độc lập cùng 1 FR</strong> — invite (async, cần accept) và assign (sync, ngay lập tức) có logic khác nhau đáng kể; dễ nhầm khi maintain nếu không tách rõ 2 method.</li><li><strong><code>assignMembersInternal</code> dùng chung với Create Workspace (3.4.12)</strong> — sửa 1 chỗ ảnh hưởng cả 2 FR.</li><li><strong>Invite endpoint trả <code>Void</code></strong> (không trả invitation info) — khác pattern Invite Agency Member (3.4.7, trả đầy đủ <code>AgencyInvitationResponse</code> kèm token) — có thể là thiếu sót cần đồng bộ pattern nếu FE cần hiển thị trạng thái invitation vừa gửi.</li><li><strong><code>skippedUserIds</code> không còn im lặng bỏ qua</strong> (khác version cũ) — cần đảm bảo FE đã cập nhật UI hiển thị cảnh báo cho các user bị skip, tránh gây hiểu nhầm &quot;thêm thành công toàn bộ&quot;.</li></ul>`,18)])])}const k=t(c,[["render",i]]);export{m as __pageData,k as default};
